local A,S,K="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/","","\139\150\44\254\119\208\138\67\229\218\91\46\232"
local p={}local j=0 local kl=#K
local function e(x)j=j+1 return string.char(bit32.bxor(x,K:byte((j-1)%kl+1)))end
local function h(c)local i=A:find(c,1,true)if i then return i-1 end return nil end
for i=1,#S,4 do
local a,b,c,d=h(S:sub(i,i)),h(S:sub(i+1,i+1)),h(S:sub(i+2,i+2)),h(S:sub(i+3,i+3))
p[#p+1]=e(a*4+math.floor((b or 0)/16))
if c then p[#p+1]=e((b%16)*16+math.floor(c/4))if d then p[#p+1]=e((c%4)*64+d)end end
end
local f=loadstring(table.concat(p))assert(f)f()
